/* Revisão circular Modo MbB: leitura didática em etapas, sem alterar os programas. */
(() => {
  const roteiros = [{"id":"preparacao","section":"b6-prep","anchor":"8. Código do LED","title":"Preparação — entendendo o LED antes de conectar","intro":"O ESP32 já executou o primeiro programa no Monitor Serial. Agora observe como uma decisão escrita no código se transforma em uma ação visível no LED.","items":[["const int LED = 23;","Damos o nome LED ao GPIO 23. Assim, o programa usa um nome com significado em vez de repetir o número do pino."],["void setup() / void loop()","setup() prepara o circuito uma vez; loop() repete o comportamento enquanto a placa estiver executando o programa."],["pinMode(LED, OUTPUT)","Configura o GPIO como saída. Antes disso, não devemos pressupor que ele já esteja preparado para acionar o LED."],["digitalWrite(LED, HIGH / LOW)","HIGH aplica nível lógico alto; LOW aplica nível lógico baixo. Com a montagem proposta, isso liga e desliga o LED."],["delay(1000)","Faz o programa aguardar cerca de 1.000 milissegundos (1 segundo) antes do próximo comando."]],"checkpoint":"Antes de executar, troque somente delay(1000) por delay(250) nos dois lugares. Preveja como ficará o piscar; depois teste e restaure o valor.","caution":"Segurança: os GPIOs do ESP32 trabalham com lógica de 3,3 V. Não aplique 5 V diretamente a eles."},{"id":"bluetooth","section":"b6-1","anchor":"5. Entendendo as novidades","title":"Bluetooth — de uma letra a uma ação","intro":"O celular envia uma letra. Bluetooth transporta a mensagem, mas é o programa que interpreta seu conteúdo e decide se o LED deve acender ou apagar.","items":[["#include &quot;BluetoothSerial.h&quot;","Disponibiliza a biblioteca da comunicação Bluetooth Classic/SPP no ESP32 original usado nesta atividade."],["BluetoothSerial SerialBT;","Cria um objeto chamado SerialBT: é por meio dele que o programa acessa os recursos dessa comunicação."],["Serial.begin(115200) / SerialBT.begin(&quot;MBB-ESP32&quot;)","O primeiro inicia o Monitor Serial em 115200 bits por segundo; o segundo inicia o Bluetooth com um nome visível ao dispositivo que vai conectar."],["SerialBT.available() / SerialBT.read()","available() informa quantos bytes aguardam leitura. Dentro do if, read() lê um byte e char comando guarda o caractere recebido para a comparação seguinte."],["comando == 'L' || comando == 'l'","== compara valores; || significa OU. A condição aceita L maiúsculo ou minúsculo. Aspas simples representam um caractere."],["digitalWrite() / SerialBT.println()","digitalWrite() muda o nível do GPIO; SerialBT.println() envia ao celular uma mensagem confirmando o que ocorreu."]],"checkpoint":"Envie L, l, D e X. Antes de cada envio, preveja a reação do LED. Explique por que X não produz nenhuma das duas ações programadas.","caution":"No Wokwi, o Monitor Serial permite testar a lógica dos comandos. O simulador não cria uma conexão de rádio Bluetooth real."},{"id":"wifi","section":"b6-2","anchor":"5. Entendendo as novidades","title":"Wi-Fi — entrar na rede é diferente de acessar a Internet","intro":"Antes de abrir uma página do ESP32, ele precisa primeiro participar de uma rede local. O próximo resultado observável será o endereço IP exibido no Monitor Serial.","items":[["#include &lt;WiFi.h&gt;","Importa a biblioteca utilizada para configurar e consultar a conexão Wi-Fi."],["const char* ssid / const char* senha","Guardam referências a textos: o nome da rede e sua senha. O asterisco faz parte da declaração do ponteiro para caracteres."],["WiFi.mode(WIFI_STA)","Define o modo estação: o ESP32 entra como dispositivo em uma rede existente."],["WiFi.begin(ssid, senha)","Inicia a tentativa de conexão com os dados informados. Não significa que já esteja conectado."],["WiFi.status() != WL_CONNECTED","!= significa 'diferente de'. Enquanto o estado não for conectado, a condição do while será verdadeira."],["while (...) / delay(500)","O while repete a espera; delay(500) aguarda meio segundo entre as verificações. Neste exemplo, uma senha incorreta pode deixá-lo esperando indefinidamente."],["WiFi.localIP()","Mostra o endereço IP atribuído à placa depois da conexão. Esse endereço será utilizado na etapa de servidor HTTP."]],"checkpoint":"Sem executar, responda: o que aparecerá se a senha estiver incorreta? Por que um endereço IP local não prova que exista conexão com a Internet?","caution":"No Wokwi, use a rede virtual Wokwi-GUEST conforme a prática. Não compartilhe arquivos de código contendo a senha real da escola ou de casa."},{"id":"http-servidor","section":"b6-3","anchor":"7. Como o servidor funciona","title":"HTTP — parte A: o ESP32 atende ao navegador","intro":"Nesta parte, o navegador é o cliente: ele solicita uma página ou uma ação. O ESP32 é o servidor: recebe a requisição e devolve a resposta.","items":[["WebServer servidor(80)","Prepara um servidor HTTP para escutar a porta 80 do ESP32."],["String criarPagina() / return pagina","Monta o texto HTML que será apresentado ao navegador e devolve esse conteúdo à função que o solicitar."],["String pagina = \"...\" / pagina += \"...\"","String guarda textos. O operador += acrescenta novos trechos ao HTML da página; no navegador, as tags montadas nesse texto viram títulos, parágrafos e links."],["digitalRead(LED) == HIGH","Consulta o nível atual do GPIO e o compara com HIGH; assim, a página pode mostrar o estado que o programa está lendo."],["servidor.on(&quot;/&quot;, mostrarPagina)","Associa o caminho / à função mostrarPagina; as rotas /ligar e /desligar chamam funções que alteram o LED."],["servidor.send(200, &quot;text/html&quot;, criarPagina())","Envia uma resposta HTTP com status 200, tipo de conteúdo HTML e corpo gerado por criarPagina()."],["servidor.begin() / servidor.handleClient()","begin() inicia o atendimento. handleClient(), dentro de loop(), precisa ser chamado repetidamente para processar as solicitações."]],"checkpoint":"Abra /ligar no navegador e explique a sequência: solicitação → função ligarLED() → digitalWrite() → página de resposta.","caution":"As rotas demonstrativas não têm autenticação. Mantenha esta experiência na rede de laboratório e não a use para equipamentos críticos."},{"id":"http-cliente","section":"b6-3","anchor":"4. Como o cliente funciona","title":"HTTP — parte B: o ESP32 faz uma solicitação","intro":"Agora os papéis se invertem. O ESP32 vira cliente quando consulta uma página de outro servidor. Não é a placa que define o papel: é quem faz o pedido.","items":[["#include &lt;HTTPClient.h&gt; / HTTPClient http;","A biblioteca disponibiliza o cliente HTTP. A declaração cria um objeto chamado http para a consulta."],["http.begin(&quot;http://example.com/&quot;)","Define a URL que será consultada. O exemplo usa HTTP sem criptografia e não deve transportar dados pessoais."],["int codigo = http.GET()","Envia uma requisição GET e guarda o retorno da operação. Um código HTTP positivo pode representar uma resposta do servidor; códigos negativos indicam erros internos da biblioteca."],["if (codigo &gt; 0) / http.getString()","Só tenta ler o corpo quando houve retorno positivo. getString() obtém o texto da resposta, que pode ser longo."],["http.end()","Encerra a operação e libera os recursos usados pelo cliente HTTP."],["HTTP 200 / 404","200 é uma resposta de sucesso; 404 indica que o recurso solicitado não foi encontrado. Não confunda esses códigos HTTP com erros negativos da biblioteca."]],"checkpoint":"Quando o ESP32 consulta um endereço externo, quem é cliente? Quem é servidor? O que muda se o endereço responder 404?","caution":"A consulta HTTP é apenas demonstrativa. Para informações sensíveis, uma implementação real exige HTTPS/TLS e validação adequada."}];
  function instalar() {
    roteiros.forEach(roteiro => {
      const secao = document.getElementById(roteiro.section);
      const cards = secao?.querySelector('.cards');
      if (!cards || cards.querySelector('[data-mbb6-leitura="'+roteiro.id+'"]')) return;
      const artigos = Array.from(cards.querySelectorAll(':scope > article'));
      const ancora = artigos.find(item => (item.querySelector('h3')?.textContent || '').includes(roteiro.anchor));
      if (!ancora) return;
      const card = document.createElement('article');
      card.className = 'card wide mbb6-aprofundamento';
      card.dataset.mbb6Leitura = roteiro.id;
      const linhas = roteiro.items.map(([codigo, descricao]) =>
        '<div class="mbb6-depth-row"><div class="mbb6-depth-command"><code>'+codigo+'</code></div><p>'+descricao+'</p></div>'
      ).join('');
      card.innerHTML =
        '<h3>Lendo o programa · '+roteiro.title+'</h3>'+
        '<div class="mbb6-depth-content">'+
          '<p class="mbb6-depth-intro">'+roteiro.intro+'</p>'+
          '<h4>Comandos e decisões, passo a passo</h4>'+
          '<div class="mbb6-depth-rows">'+linhas+'</div>'+
          '<div class="mbb6-depth-check"><strong>Agora é com você</strong><p>'+roteiro.checkpoint+'</p></div>'+
          '<p class="mbb6-depth-caution"><strong>Importante:</strong> '+roteiro.caution+'</p>'+
        '</div>';
      // A leitura ocupa o lugar da explicação resumida que repetia os comandos.
      // Nos cartões de código, entra após o programa, preservando pre e Copiar.
      const explicacao = ancora.querySelector(':scope > .explain');
      if (explicacao) explicacao.remove();
      card.querySelector('h3').remove();
      card.className = 'mbb6-leitura-integrada';
      ancora.appendChild(card);
    });
  }
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', instalar);
  else instalar();
})();